# Forward-chaining check of the BoardgameQA problem (defeasible rules, hand-encoded).
# Spinach is treated as a leafy green vegetable. Yellow is not a primary color (red/green/blue).

facts = set()
def add(f): facts.add(f)

# Initial facts
add("bee_not_tear_badger")
add("frog_has_spinach")
add("snake_reduced_hours")
add("seahorse_not_create_vampire")
frog_color_primary = "yellow" in ("red", "green", "blue")  # False

changed = True
while changed:
    before = set(facts)
    # Rule12
    if "seahorse_not_create_vampire" in facts: add("seahorse_enjoys_ant")
    # Rule23
    if "snake_reduced_hours" in facts: add("snake_tears_dove")
    # Rule2
    if "snake_tears_dove" in facts: add("woodpecker_takes_monkey")
    # Rule16 / Rule11 (not applicable: yellow not primary, age unknown); Rule21
    if "frog_has_spinach" in facts and not frog_color_primary:
        add("frog_destroys_wall_swan")
    # Rule24 (preferred over Rule6)
    if "frog_destroys_wall_swan" in facts:
        add("swan_shouts_peafowl")
    # Rule6 only if Rule24 doesn't apply
    if "seahorse_enjoys_ant" in facts and "frog_destroys_wall_swan" not in facts:
        add("swan_not_shout_peafowl")
    # Rule22 (Rule3 preferred but no rhino persuader)
    if "swan_shouts_peafowl" in facts and "someone_persuades_rhino" not in facts:
        add("swan_shouts_beaver")
    # Rule1 (Rule15 preferred, no bison trader)
    if "swan_shouts_beaver" in facts and "someone_trades_bison" not in facts:
        add("swan_unites_ostrich")
    # Rule7
    if "swan_unites_ostrich" in facts: add("beetle_trades_stork")
    # Rule5, 19, 20
    if "bee_not_tear_badger" in facts: add("bee_refuses_badger")
    if "bee_refuses_badger" in facts: add("bee_shouts_dragonfly")
    if "bee_shouts_dragonfly" in facts: add("bee_wants_fangtooth")
    # Rule14 (Rule9 preferred but flamingo smiles at bee is not known)
    if "bee_wants_fangtooth" in facts and "flamingo_smiles_bee" not in facts:
        add("bee_not_shout_beetle")
    # Rule13 (Rule8 preferred but bee creating castle for dragon is not known)
    if "woodpecker_takes_monkey" in facts and "bee_creates_dragon" not in facts:
        add("bee_not_refuse_dinosaur")
    # Rule17
    if "bee_not_refuse_dinosaur" in facts: add("bee_reveals_zebra")
    # Rule18
    if "bee_not_shout_beetle" in facts and "bee_reveals_zebra" in facts:
        add("bee_not_trade_stork")
    # Rule4
    if "bee_not_trade_stork" in facts and "beetle_trades_stork" in facts:
        add("stork_wants_goat")
    # Rule10
    if "stork_wants_goat" in facts: add("finch_not_capture_king")
    changed = facts != before

print(sorted(facts))
if "finch_not_capture_king" in facts:
    result = "disproved"
elif "finch_captures_king" in facts:
    result = "proved"
else:
    result = "unknown"
print("Derived result:", result)
print("Submitted: disproved")
print("CHECK PASS" if result == "disproved" else "CHECK FAIL")
