import json

def factorize(n):
    factors = {}
    d = 2
    m = n
    while d * d <= m:
        while m % d == 0:
            factors[d] = factors.get(d, 0) + 1
            m //= d
        d += 1 if d == 2 else 2
    if m > 1:
        factors[m] = factors.get(m, 0) + 1
    return factors

n = 33146799
f = factorize(n)

# verify product
prod = 1
for p, e in f.items():
    prod *= p ** e

def is_prime(p):
    if p < 2:
        return False
    i = 2
    while i * i <= p:
        if p % i == 0:
            return False
        i += 1
    return True

if prod == n and all(is_prime(p) for p in f):
    primes = sorted(f)
    answer = ", ".join(str(p) for p in primes)
    print(json.dumps({
        "final_answer": answer,
        "evidence": {
            "n": n,
            "factorization": {str(p): e for p, e in sorted(f.items())},
            "product_check": prod == n,
        },
    }))
else:
    print("UNSUPPORTED")
