import math, json

def F(t):
    # antiderivative of ln(1+t)/t^2, t = x-2
    return -math.log1p(t)/t + math.log(t) - math.log1p(t)

def first(eps, delta):   # integral over x in [2+delta, 2+eps]
    return F(eps) - F(delta)

def second(eps):         # integral over x in [3-eps, 3], t in [1-eps, 1]
    return F(1.0) - F(1.0 - eps)

eps = 1e-3
sec = second(eps)
vals = []
for k in range(6, 16, 3):
    d = 10.0**(-k)
    vals.append((k, first(eps, d)))
# growth per decade should approach ln(10) if the integrand ~ 1/t (log divergence)
growth = [(vals[i+1][1]-vals[i][1])/(vals[i+1][0]-vals[i][0]) for i in range(len(vals)-1)]
diverges = all(abs(g - math.log(10)) < 1e-3 for g in growth)
second_small = [second(e) for e in (1e-2, 1e-3, 1e-4)]
tends_zero = all(second_small[i+1] < second_small[i] for i in range(2)) and second_small[-1] < 1e-3

if diverges and tends_zero:
