import json
from itertools import permutations

riders = ["R", "S", "T", "Y"]
bikes = ["F", "G", "H", "J"]
R, S, T, Y = 0, 1, 2, 3

def valid(d1, d2):
    # d1[i], d2[i] = bike tested by rider i on day 1 / day 2
    for i in range(4):
        if d1[i] == d2[i]:
            return False
    for d in (d1, d2):
        if d[R] == "F" or d[Y] == "J":
            return False
    if "H" not in (d1[T], d2[T]):
        return False
    if d1[Y] != d2[S]:
        return False
    return True

options = {
    "A": lambda d1, d2: d2[R] == "G",
    "B": lambda d1, d2: d1[S] == "H",
    "C": lambda d1, d2: d2[Y] == "H",
    "D": lambda d1, d2: "J" in (d1[S], d2[S]),
    "E": lambda d1, d2: "G" in (d1[T], d2[T]),
}

scenarios = []
for d1 in permutations(bikes):
    if d1[T] != "J":
        continue
    for d2 in permutations(bikes):
        if valid(d1, d2):
            scenarios.append((d1, d2))

possible = []
counts = {}
for k, f in options.items():
    c = sum(1 for d1, d2 in scenarios if f(d1, d2))
    counts[k] = c
    if c > 0:
        possible.append(k)

if len(possible) == 1:
    ans = possible[0]
    print(json.dumps({
        "final_answer": ans,
        "evidence": {"num_valid_scenarios": len(scenarios), "option_counts": counts}
    }))
else:
    print("UNSUPPORTED")
