from itertools import product

N = 4
dom = range(N)

def subsets():
    for bits in product([0, 1], repeat=N):
        yield frozenset(i for i in dom if bits[i])

def some_not(X, Y):   # some X are not Y
    return any(i in X and i not in Y for i in dom)

def all_in(X, Y):     # all X are Y
    return all((i not in X) or (i in Y) for i in dom)

models = [(X, Y) for X in subsets() for Y in subsets()]

# Original: Some G are not C  =>  not all C are G   (G=good, C=cheap)
def original(G, C):
    return (not some_not(G, C), not all_in(C, G))   # (premise_true, concl_true)

# Option forms, as functions of (X, Y) with premise "some X are not Y"
forms = {
    "A": lambda X, Y: (some_not(X, Y), some_not(Y, X)),         # some H not P => some P not H
    "B": lambda X, Y: (some_not(X, Y), not all_in(X, Y)),       # some A not B => not all A are B
    "C": lambda X, Y: (some_not(X, Y), some_not(Y, X)),         # some motive not effect => some effect not motive
    "D": lambda X, Y: (some_not(X, Y), not all_in(Y, X)),       # some S not Ca => not all Ca are S
}

def valid(f):
    for X, Y in models:
        p, c = f(X, Y)
        if p and not c:
            return False
    return True

def orig_f(X, Y):
    return (some_not(X, Y), not all_in(Y, X))

print("Original form valid as a general inference?", valid(orig_f))

def same_form(f):
