import json
from fractions import Fraction as F

# Proof sketch: A, B completely separated means there is a continuous
# h: X -> [0,1] with h|A = 0 and h|B = 1 (this is the definition).
# Define g = (1-h)*f1 + h*f2. It is continuous as a sum and product of
# continuous real functions. On A, g = f1. On B, g = f2.
# The script checks the algebraic identities exactly on sample values.

samples = [F(-3), F(-1, 2), F(0), F(2, 7), F(5)]
ok = True
for a in samples:
    for b in samples:
        # point in A: h = 0
        h = F(0)
        if (1 - h) * a + h * b != a:
            ok = False
        # point in B: h = 1
        h = F(1)
        if (1 - h) * a + h * b != b:
            ok = False

if ok:
    print(json.dumps({
        "final_answer": "Yes. Such a continuous g always exists. Since A and B are completely "
                        "separated, there is a continuous h: X->[0,1] with h=0 on A and h=1 on B. "
                        "Take g=(1-h)f1+h f2. It is continuous, equals f1 on A and f2 on B.",
        "evidence": {"identity_checks_passed": True, "samples": len(samples) ** 2 * 2}
    }))
else:
    print("UNSUPPORTED")
```

