# Base facts relevant to the chain
facts.add("flamingo_is_teacher_assistant")   # works in education
facts.add("flamingo_has_luxury_aircraft")
facts.add("goat_notebook_18x14")

def fits(a, b, w, h):
    return (a <= w and b <= h) or (b <= w and a <= h)

if fits(18, 14, 17.8, 23.8):
    facts.add("goat_notebook_fits")

# Heads obtainable by any rule (to confirm overriders cannot be derived)
rule_heads = {
    "bear_calls_flamingo", "goat_negotiates_bear", "flamingo_dances_crab",
