}
overriders = {"unite_fangtooth", "takes_over_emperor_bee", "goat_brings_oil_tank"}
overriders_derivable = bool(overriders & rule_heads)

changed = True
while changed:
    changed = False
    def add(f):
        global changed
        if f not in facts:
            facts.add(f); changed = True
    if "flamingo_is_teacher_assistant" in facts or "flamingo_has_luxury_aircraft" in facts:
