    if "flamingo_no_surrender" in facts:
        add("flamingo_photo_snake")                          # R40
    if "flamingo_photo_snake" in facts:
        add("flamingo_swears_leopard")                       # R26
    if "goat_notebook_fits" in facts and "unite_fangtooth" not in facts:
        add("goat_negotiates_bear")                          # R11 (R42 not applicable)
