        add("flamingo_not_unite_vampire")                    # R41 (R4 not applicable)
    if "flamingo_not_unite_vampire" in facts and "flamingo_swears_leopard" in facts:
        add("flamingo_suspects_pigeon")                      # R17
    if "flamingo_suspects_pigeon" in facts:
        add("swallow_neglects_stork")                        # R23
    if "swallow_neglects_stork" in facts:
        add("swallow_smiles_dinosaur")                       # R30
    if "swallow_smiles_dinosaur" in facts:
        add("swallow_not_enjoy_beaver")                      # R29

print("overriders derivable:", overriders_derivable)
print("goat notebook fits:", "goat_notebook_fits" in facts)
print("swallow smiles at dinosaur:", "swallow_smiles_dinosaur" in facts)
print("swallow not enjoy beaver:", "swallow_not_enjoy_beaver" in facts)
# No rule concludes 'enjoys company of beaver' positively, so it cannot be proved.
if "swallow_not_enjoy_beaver" in facts and not overriders_derivable:
    print("Derived answer: disproved; submitted 'unknown'")
    print("CHECK FAIL")
