import json

facts = {
    ("suspects", "duck", "butterfly"),
    ("name", "fish", "Paco"),
    ("name", "reindeer", "Peddi"),
    ("not_hug", "ant", "flamingo"),
}

changed = True
while changed:
    changed = False
    new = set()
    # Rule1: reindeer hugs crab if first letters of names match
    n = {k: v for (t, k, v) in facts if t == "name"}
    if "reindeer" in n and "fish" in n and n["reindeer"][0] == n["fish"][0]:
        new.add(("hug", "reindeer", "crab"))
    # Rule2: suspects butterfly -> suspects otter
    for (t, a, b) in list(facts):
        if t == "suspects" and b == "butterfly":
            new.add(("suspects", a, "otter"))
    # Rule3: ant does not hug flamingo -> flamingo reveals secret to otter
    if ("not_hug", "ant", "flamingo") in facts:
        new.add(("reveals", "flamingo", "otter"))
    # Rule4: flamingo reveals to otter and duck suspects otter -> otter does not hide from dragon
    if ("reveals", "flamingo", "otter") in facts and ("suspects", "duck", "otter") in facts:
        new.add(("not_hide", "otter", "dragon"))
    if not new <= facts:
        facts |= new
        changed = True

if ("not_hide", "otter", "dragon") in facts:
    ans = "disproved"
elif ("hide", "otter", "dragon") in facts:
    ans = "proved"
else:
    ans = "unknown"

print(json.dumps({
    "final_answer": ans,
    "evidence": {
        "derived": sorted(str(f) for f in facts if f[0] in ("reveals", "not_hide") or (f[0] == "suspects" and f[2] == "otter")),
    },
}))
